<?php
require dirname(__DIR__).'/bootstrap.php';
try{$lat=filter_input(INPUT_GET,'lat',FILTER_VALIDATE_FLOAT);$lng=filter_input(INPUT_GET,'lng',FILTER_VALIDATE_FLOAT);if($lat===false||$lng===false||$lat===null||$lng===null||abs($lat)>90||abs($lng)>180)throw new RuntimeException('Coordonnées GPS invalides');$key=setting('google_geocoding_server_key');if(!$key||!function_exists('curl_init'))throw new RuntimeException('Google Geocoding non configuré');$url='https://maps.googleapis.com/maps/api/geocode/json?latlng='.rawurlencode($lat.','.$lng).'&language=fr&key='.rawurlencode($key);$c=curl_init($url);curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>10]);$raw=curl_exec($c);curl_close($c);$j=json_decode((string)$raw,true);if(($j['status']??'')!=='OK'||empty($j['results'][0]['formatted_address']))throw new RuntimeException('Adresse introuvable');json_reply(['address'=>$j['results'][0]['formatted_address']]);}catch(Throwable $e){json_reply(['error'=>$e->getMessage()],422);}